package local.spotify.unified;
import android.content.res.Configuration;
/**
 * Classic or New interface style. New resources are generated by restyle.py with the
 * "car" UI-mode qualifier, so the style is a configuration override applied together
 * with the UI scale; Classic resources stay exactly as in the BYD-derived interface.
 */
public final class HeadUnitStyle {
 public static final String CLASSIC="classic",NEW="new";
 private static volatile boolean modern=true;
 private HeadUnitStyle(){}
 public static boolean modern(){return modern;}
 static boolean modern(String value){return !CLASSIC.equals(value);}
 static Configuration apply(Configuration config,boolean value){
  modern=value;
  config.uiMode=(config.uiMode&~Configuration.UI_MODE_TYPE_MASK)|(value?Configuration.UI_MODE_TYPE_CAR:Configuration.UI_MODE_TYPE_NORMAL);
  return config;
 }
 static boolean applied(Configuration config){return (config.uiMode&Configuration.UI_MODE_TYPE_MASK)==Configuration.UI_MODE_TYPE_CAR;}
 private static final java.util.WeakHashMap<android.content.res.Resources,android.content.res.Resources> styled=new java.util.WeakHashMap<>();
 /**
  * The player's resources with the New-style UI-mode type. AppCompat's day/night handling
  * rebuilds the activity configuration without the UI-mode type set in attachBaseContext, so
  * MainActivity.getResources() returns these resources instead.
  */
 public static android.content.res.Resources resources(android.content.Context activity,android.content.res.Resources resources){
  if(!modern || resources==null || applied(resources.getConfiguration()))return resources;
  synchronized(styled){
   android.content.res.Resources result=styled.get(resources);
   if(result==null){Configuration config=apply(new Configuration(resources.getConfiguration()),true);result=activity.createConfigurationContext(config).getResources();styled.put(resources,result);}
   return result;
  }
 }
 /**
  * The interface knows Spotify's mobile ids "likeTrack"/"unlikeTrack"; Spotify Automotive
  * publishes "like"/"unlike", so its like button never appeared. New style accepts both.
  */
 public static boolean actionMatches(String expected,Object actual){
  if(expected==null)return actual==null;
  if(expected.equals(actual))return true;
  if(!modern || !(actual instanceof String))return false;
  return "likeTrack".equals(expected) && "like".equals(actual) || "unlikeTrack".equals(expected) && "unlike".equals(actual);
 }
}
